<script setup>
import {ref,onMounted} from 'vue'
import DialogShell from './DialogShell.vue'
import {voiceApi as api,stamp} from '../voice/operations'
const props=defineProps({campaignId:Number}),emit=defineEmits(['close'])
const data=ref(null),form=ref(null),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('check'),shell=ref(null),version=ref(0)
const labels={pending:'Aguardando envio',blocked:'Impedido antes do envio',submitting:'Envio em processamento',accepted:'Aceito pelo SMTP',unknown:'Resultado não confirmado',cancelled:'Cancelado'}
async function load(){busy.value=true;error.value='';try{data.value=await api('/campaigns/'+props.campaignId+'/impact');form.value={...data.value.email};version.value++}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await api('/campaigns/'+props.campaignId+'/impact','PUT',form.value);form.value={...data.value.email};version.value++;notice.value='Configuração salva. Aplicável às próximas tentativas; nenhum envio foi iniciado.'}catch(e){error.value=e.message}finally{busy.value=false}}
async function retry(id){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/campaigns/'+props.campaignId+'/impact/email/'+id+'/retry','POST',{});data.value=result;notice.value='Passo devolvido à espera. O processamento verificará novamente as regras.'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><DialogShell v-if="!form" title="Preparar teste da cadência" :busy="busy" @close="emit('close')"><p v-if="error" role="alert">{{error}}</p><p v-else>Conferindo os registros…</p></DialogShell><DialogShell v-else :key="version" ref="shell" title="Impacto após as chamadas" description="Confira a operação e prepare a continuidade por WhatsApp e e-mail." :draft="form" :busy="busy" wide @close="emit('close')">
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
 <nav class="impact-tabs" aria-label="Impacto da cadência"><button v-for="t in [['check','Conferir teste'],['email','E-mail'],['history','Histórico de e-mails']]" :key="t[0]" class="secondary" :aria-pressed="tab===t[0]" @click="tab=t[0]">{{t[1]}}</button></nav>
 <section v-if="tab==='check'"><p>Mensagens após <strong>{{data.threshold}} não atendimento(s)</strong>. Atendimentos humanos, respostas no WhatsApp e descadastros impedem a continuidade pendente. Caixa postal segue a regra de contagem da cadência.</p><div class="impact-checks"><article v-for="c in data.checks" :key="c.key" :class="c.status"><span>{{c.status==='ok'?'✓':'!'}}</span><div><strong>{{c.title}}</strong><p>{{c.detail}}</p></div></article></div><details v-for="q in data.queues" :key="q.queue.id" class="ds-section"><summary>{{q.queue.name}} · {{q.agents.counts.available}} atendente(s) disponível(is)</summary><p v-for="c in q.checks.filter(c=>c.status!=='ok')" :key="c.code"><strong>{{c.title}}</strong><br>{{c.action}}</p></details><p class="impact-note">{{data.scope}}</p></section>
 <form v-if="tab==='email'" id="cadence-email-form" @submit.prevent="save"><p class="impact-note">E-mail independente do WhatsApp, no mesmo limite de não atendimentos ({{data.threshold}}). Editar exige cadência pausada. A configuração só considera tentativas posteriores ao salvamento.</p><fieldset class="ds-section"><legend>Continuidade por e-mail</legend><label class="impact-toggle"><input v-model="form.enabled" type="checkbox"> Incluir e-mail após o limite de não atendimentos</label><label>Aguardar antes de enviar (minutos)<input v-model.number="form.delay_minutes" type="number" min="0" max="10080" required></label><label>Assunto<input v-model="form.subject" maxlength="200" required></label><label>Mensagem<textarea v-model="form.body" rows="5" maxlength="10000" required/></label><p class="impact-note">Personalize com {primeiro_nome}, {nome} e {campanha}. O link de descadastro é incluído automaticamente. Mensagens em texto simples.</p></fieldset><fieldset class="ds-section"><legend>Serviço de envio</legend><strong>{{data.transport.ready?'SMTP liberado pela administração':'Aguardando configuração da administração'}}</strong><p>Remetente: {{data.transport.from||'Não configurado'}}<br>Respostas: {{data.transport.reply_to||'Não configurado'}}<br>Limite diário: {{data.transport.daily_limit}} tentativas por empresa.</p><p class="impact-note">As respostas chegam à caixa de e-mail configurada. Entrega, leitura, cliques e respostas de e-mail ainda não são conciliados automaticamente na DiscAI. Não use a ausência desses eventos como prova de que o cliente não respondeu.</p></fieldset></form>
 <section v-if="tab==='history'"><div class="impact-totals"><span v-for="t in data.totals" :key="t.status"><strong>{{t.total}}</strong> {{labels[t.status]||t.status}}</span></div><p v-if="!data.history.length">Nenhum passo de e-mail registrado nesta cadência.</p><article v-for="h in data.history" :key="h.id" class="ds-section"><strong>{{h.destination||'E-mail ausente'}} · {{labels[h.status]||h.status}}</strong><p>{{h.reason||'Previsão: '+stamp(h.due_at)}}</p><small>{{stamp(h.created_at)}}</small><button v-if="h.status==='blocked'&&!h.submitted_at" class="secondary" @click="retry(h.id)">Reavaliar após corrigir</button></article><p class="impact-note">Até 50 registros recentes. Os totais abrangem todo o histórico da cadência. Resultado incerto nunca é reenviado automaticamente. Consulte entregas e respostas do WhatsApp no dashboard da jornada.</p></section>
 <template #footer="{close,dirty}"><small>{{dirty?'Alterações não salvas':'Conferência e preparação; nenhum disparo por esta tela.'}}</small><button class="secondary" @click="close">Fechar</button><button v-if="tab==='email'" class="primary" form="cadence-email-form" type="submit" :disabled="busy||!['paused','draft'].includes(data.campaign.status)">Salvar e-mail</button></template>
</DialogShell></template>
<style scoped>
.impact-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}.impact-tabs button[aria-pressed=true]{background:#f5ecd3;border-color:#c5a14d}.impact-checks{display:grid;grid-template-columns:1fr 1fr;gap:12px}.impact-checks article{display:flex;gap:12px;padding:18px;border:1px solid #e0e7da;border-radius:14px;background:#fafbf7}.impact-checks article>span{color:#9e782b}.impact-checks .ok>span{color:#3f7d52}.impact-checks strong{font-size:13px}.impact-checks p,.impact-note{font-size:12px;line-height:1.7;color:#657760}.impact-toggle{display:flex;flex-direction:row;gap:12px;align-items:center}.impact-toggle input{width:auto}.impact-totals{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.impact-totals span{padding:12px;background:#f3f6ee;border:1px solid #dce5d4;border-radius:10px;font-size:12px}.impact-totals strong{font-size:20px}label{display:flex;flex-direction:column;gap:8px;margin:16px 0;font-size:13px}textarea{width:100%;resize:vertical}summary{cursor:pointer}small{font-size:11px;color:#687c65}@media(max-width:650px){.impact-checks{grid-template-columns:1fr}.impact-tabs button{flex:1}}
</style>
